#import <Foundation/Foundation.h>

static NSInteger factorial(NSInteger n) {
    return n <= 1 ? 1 : n * factorial(n - 1);
}

int main(void) {
    @autoreleasepool {
        for (NSInteger i = 0; i < 3; i++) {
            NSLog(@"i=%ld", (long)i);
        }
        NSArray *items = @[@"a", @"b", @"c"];
        for (NSString *item in items) {
            NSLog(@"item=%@", item);
        }
        NSInteger n = 0;
        while (n < 2) { n++; }
        NSLog(@"factorial(5)=%ld", (long)factorial(5));
    }
    return 0;
}

