#import <Foundation/Foundation.h>

typedef NSInteger (^MathBlock)(NSInteger, NSInteger);

static NSInteger apply(NSInteger x, NSInteger y, MathBlock f) {
    return f(x, y);
}

int main(void) {
    @autoreleasepool {
        MathBlock add = ^NSInteger(NSInteger a, NSInteger b) { return a + b; };
        MathBlock mul = ^NSInteger(NSInteger a, NSInteger b) { return a * b; };
        NSLog(@"add=%ld", (long)apply(2, 3, add));
        NSLog(@"mul=%ld", (long)apply(2, 3, mul));

        NSArray *nums = @[@1, @2, @3];
        NSMutableArray *squares = [NSMutableArray array];
        for (NSNumber *n in nums) {
            [squares addObject:@(n.integerValue * n.integerValue)];
        }
        NSLog(@"%@", squares);
    }
    return 0;
}

