#import <Foundation/Foundation.h>
@interface Stack<__covariant ObjectType> : NSObject
- (void)push:(ObjectType)obj;
- (ObjectType)pop;
@end
@implementation Stack {
    NSMutableArray *_items;
}
- (instancetype)init {
    if ((self = [super init])) { _items = [NSMutableArray array]; }
    return self;
}
- (void)push:(id)obj { [_items addObject:obj]; }
- (id)pop {
    id last = _items.lastObject; if (last) { [_items removeLastObject]; }
    return last;
}
@end
int main(void) {
    @autoreleasepool {
        Stack<NSString *> *s = [Stack new];
        [s push:@"a"]; NSLog(@"%@", [s pop]);
    }
    return 0;
}

#import <Foundation/Foundation.h>
static BOOL parseInteger(NSString *text, NSInteger *out, NSError **error) {
    NSScanner *scanner = [NSScanner scannerWithString:text];
    NSInteger value;
    if ([scanner scanInteger:&value] && scanner.isAtEnd) {
        *out = value; return YES;
    }
    if (error) {
        *error = [NSError errorWithDomain:@"ParseError" code:1 userInfo:@{NSLocalizedDescriptionKey: @"不是合法整数"}];
    }
    return NO;
}
int main(void) {
    @autoreleasepool {
        NSInteger value = 0;
        NSError *err = nil;
        if (parseInteger(@"42", &value, &err)) {
            NSLog(@"value=%ld", (long)value);
        }
        if (!parseInteger(@"x", &value, &err)) {
            NSLog(@"error=%@", err.localizedDescription);
        }
    }
    return 0;
}

