#import <Foundation/Foundation.h>

int main(void) {
    @autoreleasepool {
        NSString *text = @"电话 010-1234，备用 021-5678";
        NSError *error = nil;
        NSRegularExpression *regex =
            [NSRegularExpression regularExpressionWithPattern:@"(\\d{3})-(\\d{4})"
                                                      options:0
                                                        error:&error];
        NSArray<NSTextCheckingResult *> *matches =
            [regex matchesInString:text options:0 range:NSMakeRange(0, text.length)];
        for (NSTextCheckingResult *m in matches) {
            NSString *area = [text substringWithRange:[m rangeAtIndex:1]];
            NSString *num = [text substringWithRange:[m rangeAtIndex:2]];
            NSLog(@"%@ => %@", area, num);
        }
        NSString *replaced = [regex stringByReplacingMatchesInString:text
                                                            options:0
                                                              range:NSMakeRange(0, text.length)
                                                       withTemplate:@"[$1]"];
        NSLog(@"%@", replaced);
    }
    return 0;
}

