#import <Foundation/Foundation.h>
#import <sqlite3.h>
int main(void) {
    @autoreleasepool {
        sqlite3 *db = NULL;
        if (sqlite3_open(":memory:", &db) != SQLITE_OK) {
            NSLog(@"打开失败");
            return 1;
        }
        sqlite3_exec(db, "CREATE TABLE user(id INTEGER PRIMARY KEY, name TEXT)", NULL, NULL, NULL);
        sqlite3_stmt *stmt = NULL;
        sqlite3_prepare_v2(db, "INSERT INTO user(name) VALUES (?)", -1, &stmt, NULL);
        sqlite3_bind_text(stmt, 1, "Ada", -1, SQLITE_TRANSIENT);
        sqlite3_step(stmt);
        sqlite3_finalize(stmt);

        sqlite3_prepare_v2(db, "SELECT id, name FROM user", -1, &stmt, NULL);
        while (sqlite3_step(stmt) == SQLITE_ROW) {
            NSLog(@"%d: %s", sqlite3_column_int(stmt, 0), (const char *)sqlite3_column_text(stmt, 1));
        }
        sqlite3_finalize(stmt);
        sqlite3_close(db);
    }
    return 0;
}

#import <Foundation/Foundation.h>

int main(void) {
    @autoreleasepool {
        NSURL *url = [NSURL URLWithString:@"https://httpbin.org/get"];
        NSURLRequest *req = [NSURLRequest requestWithURL:url];
        dispatch_semaphore_t sem = dispatch_semaphore_create(0);

        NSURLSessionDataTask *task =
            [[NSURLSession sharedSession] dataTaskWithRequest:req
                                            completionHandler:^(NSData *data, NSURLResponse *resp, NSError *err) {
                if (err) {
                    NSLog(@"错误: %@", err.localizedDescription);
                } else {
                    NSDictionary *json = [NSJSONSerialization JSONObjectWithData:data options:0 error:nil];
                    NSLog(@"status=%ld url=%@", (long)[(NSHTTPURLResponse *)resp statusCode], json[@"url"]);
                }
                dispatch_semaphore_signal(sem);
            }];
        [task resume];
        dispatch_semaphore_wait(sem, DISPATCH_TIME_FOREVER);
    }
    return 0;
}

