#import <Foundation/Foundation.h>

int main(int argc, const char *argv[]) {
    @autoreleasepool {
        if (argc < 2) {
            fprintf(stderr, "用法: %s FILE...\n", argv[0]);
            return 1;
        }
        for (int i = 1; i < argc; i++) {
            NSString *path = [NSString stringWithUTF8String:argv[i]];
            NSError *error = nil;
            NSString *content = [NSString stringWithContentsOfFile:path
                                                          encoding:NSUTF8StringEncoding
                                                             error:&error];
            if (!content) {
                fprintf(stderr, "读取失败: %s\n", error.localizedDescription.UTF8String);
                continue;
            }
            NSUInteger lines = [[content componentsSeparatedByString:@"\n"] count] - 1;
            printf("%lu\t%lu\t%s\n", (unsigned long)lines, (unsigned long)content.length, argv[i]);
        }
    }
    return 0;
}

